// n8n Code node: validate and normalize one webhook request before any external call.
const body = $input.first().json.body;
const fail = (message) => [{ json: { valid: false, error: { code: 'INVALID_INPUT', message } } }];
const object = (value) => value !== null && typeof value === 'object' && !Array.isArray(value);
const money = (value) => typeof value === 'number' && Number.isFinite(value)
  && Math.abs(value) <= 1000000 && Math.abs(value * 100 - Math.round(value * 100)) < 0.000001;
const date = (value) => typeof value === 'string' && /^\d{4}-\d{2}-\d{2}$/.test(value)
  && !Number.isNaN(Date.parse(value + 'T00:00:00Z'))
  && new Date(value + 'T00:00:00Z').toISOString().slice(0, 10) === value;

if (!object(body)) return fail('Send a JSON object in the request body.');
if (body.question !== undefined && (typeof body.question !== 'string' || body.question.length > 500)) {
  return fail('question must be a string of at most 500 characters.');
}
if (body.university !== undefined && (typeof body.university !== 'string' || body.university.length > 100)) {
  return fail('university must be a string of at most 100 characters.');
}
if (body.noFamilySupport !== undefined && typeof body.noFamilySupport !== 'boolean') {
  return fail('noFamilySupport must be a boolean.');
}
const f = body.finance;
if (!object(f)) return fail('finance is required.');
if (!date(f.startDate) || !date(f.nextMaintenanceLoanDate)) {
  return fail('Finance dates must be real YYYY-MM-DD dates.');
}
const start = Date.parse(f.startDate + 'T00:00:00Z');
const end = Date.parse(f.nextMaintenanceLoanDate + 'T00:00:00Z');
if (end <= start || end - start > 366 * 86400000) {
  return fail('nextMaintenanceLoanDate must be within 366 days after startDate.');
}
if (!money(f.openingBalance)) return fail('openingBalance must be a finite amount with at most two decimal places.');
if (!Array.isArray(f.transactions) || f.transactions.length > 100) {
  return fail('transactions must be an array of at most 100 items.');
}
for (const tx of f.transactions) {
  if (!object(tx) || !date(tx.date) || tx.date < f.startDate || tx.date >= f.nextMaintenanceLoanDate
    || !money(tx.amount) || tx.amount === 0 || typeof tx.label !== 'string'
    || tx.label.trim().length === 0 || tx.label.length > 80) {
    return fail('Each transaction needs a date in the forecast window, a nonzero amount, and a label of at most 80 characters.');
  }
}
const weekly = f.weeklyEssentials;
if (!object(weekly) || !date(weekly.firstDate) || weekly.firstDate < f.startDate
  || weekly.firstDate >= f.nextMaintenanceLoanDate || !money(weekly.amount) || weekly.amount < 0) {
  return fail('weeklyEssentials needs a firstDate in the forecast window and a nonnegative amount.');
}
return [{ json: {
  valid: true,
  question: body.question ?? '',
  university: body.university ?? '',
  noFamilySupport: body.noFamilySupport === true,
  finance: {
    startDate: f.startDate,
    openingBalance: f.openingBalance,
    nextMaintenanceLoanDate: f.nextMaintenanceLoanDate,
    transactions: f.transactions.map((tx) => ({ date: tx.date, amount: tx.amount, label: tx.label.trim() })),
    weeklyEssentials: { firstDate: weekly.firstDate, amount: weekly.amount },
  },
} }];

// n8n Code node: deterministic forecast from validated, user-supplied finance data.
const request = $input.first().json;
const f = request.finance;
const toPence = (value) => Math.round(value * 100);
const events = f.transactions.map((tx) => ({ date: tx.date, label: tx.label, amountP: toPence(tx.amount) }));
const end = Date.parse(f.nextMaintenanceLoanDate + 'T00:00:00Z');
for (let day = Date.parse(f.weeklyEssentials.firstDate + 'T00:00:00Z'); day < end; day += 7 * 86400000) {
  events.push({ date: new Date(day).toISOString().slice(0, 10), label: 'Weekly essentials', amountP: -toPence(f.weeklyEssentials.amount) });
}
events.sort((a, b) => a.date.localeCompare(b.date) || b.amountP - a.amountP || a.label.localeCompare(b.label));
let balance = toPence(f.openingBalance);
let lowest = balance;
let lowestDate = f.startDate;
let firstShortfallDate = balance < 0 ? f.startDate : null;
const timeline = [];
for (const event of events) {
  balance += event.amountP;
  timeline.push({ date: event.date, label: event.label, amount: event.amountP / 100, balance: balance / 100 });
  if (balance < lowest) { lowest = balance; lowestDate = event.date; }
  if (balance < 0 && firstShortfallDate === null) firstShortfallDate = event.date;
}
return [{ json: {
  forecast: {
    currency: 'GBP',
    scenario: 'provided_transactions',
    startDate: f.startDate,
    openingBalance: f.openingBalance,
    lowestBalance: lowest / 100,
    lowestBalanceDate: lowestDate,
    firstShortfallDate,
    hasShortfall: firstShortfallDate !== null,
    balanceBeforeNextLoan: balance / 100,
    nextMaintenanceLoanDate: f.nextMaintenanceLoanDate,
    timeline,
  },
  question: request.question,
  university: request.university,
  noFamilySupport: request.noFamilySupport,
} }];

// n8n Code node after the catalogue request. Keep this ranking aligned with retrieve.mjs.
const catalogue = $input.first().json;
const request = $('Calculate forecast').first().json;
const forecast = request.forecast;
const resources = catalogue?.resources;
const usable = Array.isArray(resources) && resources.length > 0 && resources.every((source) =>
  source && typeof source.id === 'string' && typeof source.title === 'string'
  && typeof source.url === 'string' && /^https:\/\//.test(source.url)
  && Array.isArray(source.tags) && source.tags.every((tag) => typeof tag === 'string')
  && (source.university === undefined || typeof source.university === 'string')
  && (source.requiresNoFamilySupport === undefined || typeof source.requiresNoFamilySupport === 'boolean'));
if (!usable) {
  return [{ json: { ...request, supportSources: [], supportStatus: 'unavailable', catalogueCheckedAt: null } }];
}

const questionWords = new Set(String(request.question ?? '').toLowerCase().match(/[a-z]+/g) ?? []);
const university = String(request.university ?? '').trim().toLowerCase();
const manchester = university === 'university of manchester' || university === 'manchester';
const noFamilySupport = request.noFamilySupport === true;
const shortfall = forecast.hasShortfall === true;
const supportSources = resources
  .filter((source) => !source.university || (manchester && source.university === 'university of manchester'))
  .filter((source) => !source.requiresNoFamilySupport || noFamilySupport)
  .map((source) => ({
    source,
    score: source.tags.filter((tag) => questionWords.has(tag)).length * 2
      + (shortfall && source.tags.includes('hardship') ? 4 : 0)
      + (shortfall && source.tags.includes('shortfall') ? 2 : 0)
      + (noFamilySupport && source.id === 'manchester-estranged' ? 7 : 0)
      + (source.id === 'student-minds-budget' ? 1 : 0),
  }))
  .sort((a, b) => b.score - a.score || a.source.id.localeCompare(b.source.id))
  .slice(0, 3)
  .map(({ source }) => source);

return [{ json: { ...request, supportSources, supportStatus: 'ok', catalogueCheckedAt: catalogue.checkedAt ?? null } }];

// n8n Code node after Anthropic. The model can select a draft focus, never response text or URLs.
const selected = $('Select support sources').first().json;
const forecast = selected.forecast;
const money = (value) => (value < 0 ? '-£' : '£') + Math.abs(value).toFixed(2);
const shortfall = forecast.firstShortfallDate
  ? `Your first projected shortfall is on ${forecast.firstShortfallDate}.`
  : 'There is no projected shortfall before the next maintenance loan.';
const explanation = `Your projected lowest balance is ${money(forecast.lowestBalance)} on ${forecast.lowestBalanceDate}. ${shortfall} Your balance before the next maintenance loan on ${forecast.nextMaintenanceLoanDate} is ${money(forecast.balanceBeforeNextLoan)}. This estimate uses the transactions you supplied.`;
const drafts = {
  general: 'Hello, I would like to discuss my financial situation and ask what support options may be available. Could you tell me what information you need? Thank you.',
  rent: 'Hello, I am concerned about covering my rent and would like to discuss possible support options. Could you tell me what information you need? Thank you.',
  budget: 'Hello, I would like help reviewing my budget and understanding what support options may be available. Could you tell me what information you need? Thank you.',
};
const incoming = $input.first().json;
const raw = incoming?.merged_response ?? incoming?.content?.filter((part) => part.type === 'text').map((part) => part.text).join('\n');
let focus = 'general';
let draftStatus = 'fallback';
try {
  const parsed = JSON.parse(raw);
  if (parsed && typeof parsed === 'object' && ['general', 'rent', 'budget'].includes(parsed.focus)) {
    focus = parsed.focus;
    draftStatus = 'model';
  }
} catch (error) { /* Use the general draft when Anthropic fails or returns invalid JSON. */ }
return [{ json: {
  forecast,
  explanation,
  draft: drafts[focus],
  supportSources: selected.supportSources,
  supportStatus: selected.supportStatus,
  draftStatus,
  catalogueCheckedAt: selected.catalogueCheckedAt,
} }];
